src/integrations/riscv_cpu/recursive_seg:
//! One real-capture functional gate for the SegmentV2 non-core owner.
//!
//! This helper deliberately accepts the already prepared native leaf so the
//! shared ingress gate pays for native proving exactly once. It exercises no
//! outer STARK; the full proof belongs to the aggregate cohort gate.

const std = @import("std");
const stwo_core = @import("stwo_core");
const frontend = @import("stwo_riscv_frontend");
const integration = @import("stwo_riscv_cpu_integration");

const subject = @import("recursive_segment_v2_noncore_owner.zig");
const core_outer = integration.recursive_fri_outer;
const leaf_outer = @import("recursive_segment_v2_leaf_outer.zig");

const M31 = stwo_core.fields.m31.M31;
const recursion = frontend.recursion;
const manifest_mod = recursion.air.segment_outer_adapter_manifest_v2;
const universal = recursion.air.universal_challenges;
const shared_provider = recursion.air.universal_shared_provider;

pub const Error = error{
    CachedGenerationMismatch,
    CoreTreeMutation,
    ForeignContextAccepted,
    InteractionCacheMutation,
    RelationContextDidNotChange,
    TreePublicationEmpty,
};

pub fn runPrepared(
    allocator: std.mem.Allocator,
    prepared: *const leaf_outer.PreparedNativeV2LeafOuter,
) !void {
    try prepared.validate();
    const source_preflight = subject.PreflightV2.init(prepared) catch |err| {
        return failStage("preflight", err);
    };
    var changed_preflight = source_preflight;
    changed_preflight.transcript_prepared.source_id[0] ^= 1;
    try std.testing.expectError(error.SourceMismatch, changed_preflight.validateAgainst(prepared));
    changed_preflight = source_preflight;
    changed_preflight.input_provider_shape = try @TypeOf(changed_preflight.input_provider_shape).init(
        @as(usize, changed_preflight.input_provider_shape.claim_count) + 1,
    );
    try std.testing.expectError(error.SourceManifestMismatch, changed_preflight.validateAgainst(prepared));
    // Only the copied header changes; no borrowed trace or source is mutated
    // or destroyed by this constructor-ingress rejection.
    var changed_prepared = prepared.*;
    changed_prepared.format_version +%= 1;
    try std.testing.expectError(error.IdentityMismatch, subject.PreflightV2.init(&changed_prepared));
    var public_native_relations = subject.nativeRelations(prepared);
    const public_native_inputs = subject.publicInputs(
        prepared,
        &public_native_relations,
    );
    var public_native_sum_source = recursion
        .segment_public_native_sum_authority_v2.SourceV2.init(
        allocator,
        &source_preflight.public_prepared,
        public_native_inputs,
    ) catch |err| return failStage("public_native_sum_source", err);
    defer public_native_sum_source.deinit();
    var log_sizes = [_]u32{0} ** subject.UNIVERSAL_COMPONENT_COUNT;
    try source_preflight.installLogSizes(&log_sizes);
    for (
        prepared.rows_18_34_core.log_sizes,
        core_outer.NATIVE_V2_CORE_FIRST_ROW..,
    ) |log_size, row| log_sizes[row] = log_size;

    // The boundary-independent core receipt counts only its suffix. Row 34
    // commits the admitted transcript + authority prefix and the core suffix
    // as one provider, so install its complete minimal domain here.
    const complete_poseidon_calls = try std.math.add(
        usize,
        prepared.row34_boundary_prefix_calls.len,
        prepared.rows_18_34_core.core_poseidon_call_count,
    );
    log_sizes[34] = @intCast(@max(
        @as(usize, 1),
        std.math.log2_int_ceil(usize, complete_poseidon_calls),
    ));
    const manifest = manifest_mod.buildWithProviderShape(
        log_sizes,
        &source_preflight.transcript_manifest,
        &source_preflight.statement_manifest,
        &source_preflight.public_manifest,
        &source_preflight.boundary_manifest,
        source_preflight.input_provider_shape,
    ) catch |err| return failStage("manifest", err);

    var init_timer = try std.time.Timer.start();
    const owner = try allocator.create(subject.Owner);
    subject.Owner.initInPlace(
        owner,
        allocator,
        prepared,
        &manifest,
        &public_native_sum_source,
    ) catch |err| {
        allocator.destroy(owner);
        return failStage("owner_init", err);
    };
    const init_ns = init_timer.read();
    defer {
        owner.deinit();
        allocator.destroy(owner);
    }
    owner.validate() catch |err| return failStage("owner_validate", err);

    var tree0 = PublicationTree.init(
        allocator,
        &manifest,
        manifest_mod.PREPROCESSED_TREE_INDEX,
    ) catch |err| return failStage("tree0_init", err);
    defer tree0.deinit();
    var tree1 = PublicationTree.init(
        allocator,
        &manifest,
        manifest_mod.MAIN_TREE_INDEX,
    ) catch |err| return failStage("tree1_init", err);
    defer tree1.deinit();
    var tree2 = PublicationTree.init(
        allocator,
        &manifest,
        manifest_mod.INTERACTION_TREE_INDEX,
    ) catch |err| return failStage("tree2_init", err);
    defer tree2.deinit();
    var publish_01_timer = try std.time.Timer.start();
    owner.fillPreprocessedInto(&manifest, tree0.columns) catch |err|
        return failStage("tree0_fill", err);
    owner.fillMainInto(&manifest, tree1.columns) catch |err|
        return failStage("tree1_fill", err);
    const publish_01_ns = publish_01_timer.read();
    if (!containsNonZero(tree0.storage) or !containsNonZero(tree1.storage))
        return error.TreePublicationEmpty;
    if (!coreRowsAreZero(&manifest, manifest_mod.PREPROCESSED_TREE_INDEX, tree0.columns) or
        !coreRowsAreZero(&manifest, manifest_mod.MAIN_TREE_INDEX, tree1.columns))
    {
        return error.CoreTreeMutation;
    }

    // Use an actual transcript draw distinct from ingress admission. This is
    // the lifecycle check that forces boundary Tree 2 regeneration while the
    // owner itself enforces byte equality for committed Tree 0/1.
    var channel = leaf_outer.Engine.Channel{};
    channel.mixU32s(&.{ 0x4e43_5632, 1, 38, 47 });
    const relations = universal.UniversalRelations.draw(allocator, &channel) catch |err|
        return failStage("relation_draw", err);
    const provider_relations = shared_provider.SharedProviderRelations.init(
        &relations,
    ) catch |err| return failStage("provider_relations", err);
    var interaction_timer = try std.time.Timer.start();
    const generated = owner.prepareInteractions(
        allocator,
        &relations,
        &provider_relations,
    ) catch |err| return failStage("interaction_prepare", err);
    const interaction_ns = interaction_timer.read();
    try generated.validateCachedAgainst(owner, &relations, &provider_relations);
    if (std.mem.eql(
        u8,
        &owner.boundary_active_prepared.?.outer_relation_context_sha_id,
        &prepared.authority_prepared.outer_relation_context_sha_id,
    )) return error.RelationContextDidNotChange;

    var publish_2_timer = try std.time.Timer.start();
    const published = owner.fillInteractionInto(&manifest, tree2.columns) catch |err|
        return failStage("tree2_fill", err);
    const publish_2_ns = publish_2_timer.read();
    if (!std.meta.eql(generated, published) or !containsNonZero(tree2.storage))
        return error.TreePublicationEmpty;
    if (!coreRowsAreZero(
        &manifest,
        manifest_mod.INTERACTION_TREE_INDEX,
        tree2.columns,
    )) return error.CoreTreeMutation;

    // Generic engine validation is intentionally cached and allocation-free.
    // Repeating it here protects the performance contract from an accidental
    // reintroduction of the 21-row independent audit replay.
    const validation_iterations: usize = 4;
    var cached_timer = try std.time.Timer.start();
    for (0..validation_iterations) |_| try generated.validateCachedAgainst(
        owner,
        &relations,
        &provider_relations,
    );
    const cached_validation_ns = cached_timer.read();
    const cached = try owner.prepareInteractions(
        allocator,
        &relations,
        &provider_relations,
    );
    if (!std.meta.eql(generated, cached))
        return error.CachedGenerationMismatch;

    // A second challenge context is rejected before cached Tree 2, workspaces,
    // or the active pointer-free receipt can change.
    const receipt_before = owner.active_generated.?;
    const tree_before = try owner.interactionTreeIdentity();
    const admission_provider = try shared_provider.SharedProviderRelations.init(
        &prepared.outer_relations,
    );
    if (owner.prepareInteractions(
        allocator,
        &prepared.outer_relations,
        &admission_provider,
    )) |_| return error.ForeignContextAccepted else |_| {}
    if (!std.meta.eql(receipt_before, owner.active_generated.?))
        return error.InteractionCacheMutation;
    const tree_after = try owner.interactionTreeIdentity();
    if (!std.mem.eql(u8, &tree_before, &tree_after))
        return error.InteractionCacheMutation;

    std.debug.print(
        "\nV2_NONCORE_OWNER_REAL rows={d} init_ms={d:.3} " ++
            "publish_01_ms={d:.3} interaction_ms={d:.3} " ++
            "publish_2_ms={d:.3} cached_validate_ns={d} " ++
            "cached_validate_iterations={d} hot_allocations={d}/{d}/{d} " ++
            "cold_independent_audit_replays={d}\n",
        .{
            subject.OWNED_ROW_COUNT,
            milliseconds(init_ns),
            milliseconds(publish_01_ns),
            milliseconds(interaction_ns),
            milliseconds(publish_2_ns),
            cached_validation_ns,
            validation_iterations,
            subject.HOT_TREE_HEAP_ALLOCATIONS[0],
            subject.HOT_TREE_HEAP_ALLOCATIONS[1],
            subject.HOT_TREE_HEAP_ALLOCATIONS[2],
            subject.COLD_INDEPENDENT_AUDIT_REPLAYS_PER_GENERATION,
        },
    );
}

const PublicationTree = struct {
    allocator: std.mem.Allocator,
    columns: [][]M31,
    storage: []M31,

    fn init(
        allocator: std.mem.Allocator,
        manifest: *const manifest_mod.Manifest,
        tree: usize,
    ) !PublicationTree {
        const column_count: usize = switch (tree) {
            manifest_mod.PREPROCESSED_TREE_INDEX => manifest.total_preprocessed_columns,
            manifest_mod.MAIN_TREE_INDEX => manifest.total_main_columns,
            manifest_mod.INTERACTION_TREE_INDEX => manifest.total_interaction_columns,
            else => return error.InvalidTreeIndex,
        };
        const columns = try allocator.alloc([]M31, column_count);
        errdefer allocator.free(columns);
        for (columns) |*column| column.* = @constCast((&[_]M31{})[0..]);
        var words: usize = 0;
        for (manifest.roster_rows[0..manifest.roster_count]) |row| {
            const placement = manifest.placements[row].?;
            const count: usize = switch (tree) {
                manifest_mod.PREPROCESSED_TREE_INDEX => placement.geometry.preprocessed_columns,
                manifest_mod.MAIN_TREE_INDEX => placement.geometry.main_columns,
                manifest_mod.INTERACTION_TREE_INDEX => placement.geometry.interaction_columns,
                else => unreachable,
            };
            const rows = @as(usize, 1) << @intCast(placement.geometry.log_size);
            words = try std.math.add(
                usize,
                words,
                try std.math.mul(usize, count, rows),
            );
        }
        const storage = try allocator.alloc(M31, words);
        errdefer allocator.free(storage);
        @memset(storage, M31.zero());
        var cursor: usize = 0;
        for (manifest.roster_rows[0..manifest.roster_count]) |row| {
            const placement = manifest.placements[row].?;
            const offset: usize = switch (tree) {
                manifest_mod.PREPROCESSED_TREE_INDEX => placement.preprocessed_offset,
                manifest_mod.MAIN_TREE_INDEX => placement.main_offset,
                manifest_mod.INTERACTION_TREE_INDEX => placement.interaction_offset,
                else => unreachable,
            };
            const count: usize = switch (tree) {
                manifest_mod.PREPROCESSED_TREE_INDEX => placement.geometry.preprocessed_columns,
                manifest_mod.MAIN_TREE_INDEX => placement.geometry.main_columns,
                manifest_mod.INTERACTION_TREE_INDEX => placement.geometry.interaction_columns,
                else => unreachable,
            };
            const rows = @as(usize, 1) << @intCast(placement.geometry.log_size);
            for (columns[offset..][0..count]) |*column| {
                column.* = storage[cursor..][0..rows];
                cursor += rows;
            }
        }
        std.debug.assert(cursor == storage.len);
        return .{ .allocator = allocator, .columns = columns, .storage = storage };
    }

    fn deinit(self: *PublicationTree) void {
        self.allocator.free(self.storage);
        self.allocator.free(self.columns);
        self.* = undefined;
    }
};

fn containsNonZero(values: []const M31) bool {
    for (values) |value| if (!value.isZero()) return true;
    return false;
}

fn coreRowsAreZero(
    manifest: *const manifest_mod.Manifest,
    tree: usize,
    columns: []const []M31,
) bool {
    for (core_outer.NATIVE_V2_CORE_FIRST_ROW..core_outer.NATIVE_V2_CORE_LAST_ROW + 1) |row| {
        const placement = manifest.placements[row].?;
        const offset: usize = switch (tree) {
            manifest_mod.PREPROCESSED_TREE_INDEX => placement.preprocessed_offset,
            manifest_mod.MAIN_TREE_INDEX => placement.main_offset,
            manifest_mod.INTERACTION_TREE_INDEX => placement.interaction_offset,
            else => return false,
        };
        const count: usize = switch (tree) {
            manifest_mod.PREPROCESSED_TREE_INDEX => placement.geometry.preprocessed_columns,
            manifest_mod.MAIN_TREE_INDEX => placement.geometry.main_columns,
            manifest_mod.INTERACTION_TREE_INDEX => placement.geometry.interaction_columns,
            else => return false,
        };
        for (columns[offset..][0..count]) |column|
            for (column) |value| if (!value.isZero()) return false;
    }
    return true;
}

fn milliseconds(nanoseconds: u64) f64 {
    return @as(f64, @floatFromInt(nanoseconds)) / std.time.ns_per_ms;
}

fn failStage(stage: []const u8, err: anyerror) anyerror {
    std.debug.print("\nV2_NONCORE_OWNER_REAL_FAIL stage={s} error={s}\n", .{
        stage,
        @errorName(err),
    });
    return err;
}

//! One real generic-Poseidon V2 native proof crossing the complete owned
//! capture-to-recursive-preparation boundary.  This is deliberately separate
//! from the millisecond mutation root so routine development stays cheap.
const std = @import("std");
const stwo_core = @import("stwo_core");
const frontend = @import("stwo_riscv_frontend");
const integration = @import("stwo_riscv_cpu_integration");
const postcard = @import("interop_postcard");
const core_outer = integration.recursive_fri_outer;
const subject = @import("recursive_segment_v2_leaf_outer.zig");
const memory_workload = @import("recursive_segment_v2_memory_workload.zig");
const noncore_gate = @import("recursive_segment_v2_noncore_owner_real_gate.zig");
const M31 = stwo_core.fields.m31.M31;
const prover = frontend.prover_mod;
const runner = frontend.runner;
const recursion = frontend.recursion;
const segment_v2 = recursion.segment_statement_v2;
const span = recursion.span_statement;
const protocol = recursion.protocol;
const channel = recursion.poseidon2_channel;
const schedule = recursion.air.verifier_schedule;
const Engine = subject.Engine;
/// Only hooks implementing `runTupleClosureDiagnostic` may use this flag.
/// The ordinary proof and verification gate always runs in full.
pub const TUPLE_CLOSURE_DIAGNOSTIC_ENV =
    "STWO_RECURSION_OUTER_CLOSURE_DIAGNOSTIC";

const native_ingress = @import("recursive_segment_v2_native_ingress.zig");
const test_config = native_ingress.DEVELOPMENT_CONFIG;

test "generic Poseidon2 native V2 capture prepares the owned recursive leaf" {
    try runGate(std.testing.allocator);
}

/// Direct heavy-gate entrypoint. The lean executable imports this declaration
/// without asking Zig's test runner to discover and codegen every transitive
/// dependency test, which keeps optimized recursion iteration practical.
pub fn runGate(allocator: std.mem.Allocator) !void {
    return runGateWithHook(allocator, NoOpHook);
}

/// Executes the one authoritative native-ingress fixture and exposes the
/// authenticated prepared leaf only after every core schedule, provider, and
/// independent-regeneration check below has passed. Hooks cannot influence
/// native proving, verification, capture construction, or core admission.
pub fn runGateWithHook(
    allocator: std.mem.Allocator,
    comptime Hook: type,
) !void {
    return runGateWithHookForSteps(Engine, allocator, Hook, 1, true, null, 0);
}

/// Same native proof and recursive admission, without the independent
/// component/recorder regression fleet. The complete outer proof hook remains
/// mandatory; this bounded ladder cannot select block-sized execution.
pub fn runSizedGateWithHook(
    allocator: std.mem.Allocator,
    comptime Hook: type,
    native_steps: usize,
) !void {
    return runSizedGateWithNativeEngine(Engine, allocator, Hook, native_steps);
}

pub fn runSizedGateWithNativeEngine(
    comptime NativeEngine: type,
    allocator: std.mem.Allocator,
    comptime Hook: type,
    native_steps: usize,
) !void {
    return runSizedGateWithInitialRegister7(NativeEngine, allocator, Hook, native_steps, 0);
}

pub fn runSizedGateWithInitialRegister7(
    comptime NativeEngine: type,
    allocator: std.mem.Allocator,
    comptime Hook: type,
    native_steps: usize,
    initial_register7: u32,
) !void {
    switch (native_steps) {
        1, 4, 16, 64 => {},
        else => return error.InvalidNativeStepCount,
    }
    return runGateWithHookForSteps(NativeEngine, allocator, Hook, native_steps, false, null, initial_register7);
}

pub fn runMemoryGateWithNativeEngine(
    comptime NativeEngine: type,
    allocator: std.mem.Allocator,
    comptime Hook: type,
    address_count: usize,
) !void {
    switch (address_count) {
        1, 4, 16 => {},
        else => return error.InvalidMemoryAddressCount,
    }
    return runGateWithHookForSteps(NativeEngine, allocator, Hook, memory_workload.native_steps, false, address_count, 0);
}

/// Execution-only regression for the genuine step-4 failure: a JAL-to-self
/// fixture completed early instead of consuming the requested budget. This
/// uses the exact ELF and checks that the proof path will admit below.
pub fn checkSizedWorkload(allocator: std.mem.Allocator) !void {
    const elf = frontend.testing.guest_precompile_test_elf.buildRecursionLoop();
    for ([_]u32{ 0, 0x01020304, 0x05060708 }) |initial_register7| {
        for ([_]usize{ 1, 4, 16, 64 }) |steps| {
            var session = try runner.Poseidon2ExecutionSession.init(allocator, &elf, .{});
            defer session.deinit();
            session.cpu.regs[7] = initial_register7;
            var first = try session.startSegment(steps);
            defer first.deinit();
            try validateSizedExecution(&first.base, steps, steps, initial_register7);
            var second = try session.resumeSegment(first.base.continuation.?, 16);
            defer second.deinit();
            try validateSizedExecution(&second.base, steps + 16, 16, initial_register7);
            try std.testing.expectEqualDeep(first.base.exit_cpu, second.base.entry_cpu);
        }
    }
}

fn validateSizedExecution(result: *const runner.SegmentResult, cumulative_steps: usize, segment_steps: usize, initial_register7: u32) !void {
    try std.testing.expectEqual(initial_register7, result.entry_cpu.regs[7]);
    try std.testing.expectEqual(initial_register7, result.exit_cpu.regs[7]);
    try std.testing.expectEqual(segment_steps, result.cycle_count);
    try std.testing.expectEqual(segment_steps, result.execution_trace.rows.items.len);
    try std.testing.expect(result.continuation != null);
    try std.testing.expect(result.completion_reason == null);
    // Closed-form expected state, independently checked against actual
    // execution. One initialization precedes each three-instruction iteration.
    const after_init = cumulative_steps - 1;
    const completed_iterations: u32 = @intCast(after_init / 3);
    const phase: u32 = @intCast(after_init % 3);
    const expected_counter = frontend.testing.guest_precompile_test_elf.recursion_loop_iterations -
        completed_iterations - @as(u32, if (phase == 2) 1 else 0);
    const expected_accumulator = completed_iterations + @as(u32, if (phase != 0) 1 else 0);
    try std.testing.expectEqual(expected_counter, result.exit_cpu.regs[5]);
    try std.testing.expectEqual(expected_accumulator, result.exit_cpu.regs[6]);
    try std.testing.expectEqual(@as(u32, 0x1004) + 4 * phase, result.exit_cpu.pc);
    var addi_count: usize = 0;
    var bne_count: usize = 0;
    for (result.execution_trace.rows.items) |row| switch (row.opcode) {
        .ADDI => addi_count += 1,
        .BNE => bne_count += 1,
        else => return error.UnexpectedWorkloadInstruction,
    };
    std.debug.print(
        "SEGMENT_V2_LADDER_EXECUTION segment_cycles={d} cumulative_cycles={d} " ++
            "retired_addi={d} retired_bne={d} exit_pc={x} counter={d} accumulator={d} initial_register7={x}\n",
        .{ result.cycle_count, cumulative_steps, addi_count, bne_count, result.exit_cpu.pc, result.exit_cpu.regs[5], result.exit_cpu.regs[6], initial_register7 },
    );
}

fn runGateWithHookForSteps(
    comptime NativeEngine: type,
    allocator: std.mem.Allocator,
    comptime Hook: type,
    native_steps: usize,
    comptime full_regression: bool,
    memory_addresses: ?usize,
    initial_register7: u32,
) !void {
    comptime {
        if (!@hasDecl(Hook, "run"))
            @compileError("native V2 ingress hook must declare run");
    }
    comptime {
        @import("stwo_prover_api").assertProverEngine(Engine);
        @import("stwo_prover_api").assertProverEngine(NativeEngine);
        if (NativeEngine.Hasher != Engine.Hasher or NativeEngine.Channel != Engine.Channel or
            NativeEngine.MerkleChannel != Engine.MerkleChannel or NativeEngine.ExtendedProof != Engine.ExtendedProof)
            @compileError("native backend must preserve the exact admitted Poseidon proof protocol");
        if (Engine.Channel != recursion.poseidon2_channel.Channel or
            Engine.Hasher != recursion.poseidon2_channel.MerkleHasher or
            Engine.Channel == recursion.native_scheduled_channel.Channel)
        {
            @compileError("V2 proof gate must use generic Poseidon2, never Blake2s or V1 scheduling");
        }
    }
    const elf = if (comptime full_regression)
        frontend.testing.guest_precompile_test_elf.build(false, .self_loop)
    else
        frontend.testing.guest_precompile_test_elf.buildRecursionLoop();
    const memory_elf = if (memory_addresses) |count|
        try frontend.testing.guest_precompile_test_elf.buildRecursionMemory(count)
    else
        undefined;
    const elf_bytes: []const u8 = if (memory_addresses != null) &memory_elf else &elf;
    var session = try runner.Poseidon2ExecutionSession.init(allocator, elf_bytes, .{});
    defer session.deinit();
    if (memory_addresses != null and initial_register7 != 0) return error.ConflictingWorkloadArguments;
    session.cpu.regs[7] = initial_register7;
    var left_profile = try session.startSegment(native_steps);
    defer left_profile.deinit();
    const left_result = &left_profile.base;
    try std.testing.expectEqual(@as(u64, @intCast(native_steps)), @as(u64, @intCast(left_result.cycle_count)));
    var right_profile = try session.resumeSegment(left_result.continuation.?, 16);
    defer right_profile.deinit();
    const right_result = &right_profile.base;
    if (comptime !full_regression) {
        if (memory_addresses) |count| {
            try memory_workload.validateSegment(left_result, count, native_steps, native_steps);
            try memory_workload.validateSegment(right_result, count, native_steps + 16, 16);
        } else {
            try validateSizedExecution(left_result, native_steps, native_steps, initial_register7);
            try validateSizedExecution(right_result, native_steps + 16, 16, initial_register7);
            try std.testing.expectEqualDeep(left_result.exit_cpu, right_result.entry_cpu);
        }
    }

    var declared_program = try frontend.air.program.commitment.buildDeclared(
        allocator,
        left_result.execution_trace.rows.items,
        left_result.rw_memory.program_words,
        null,
    );
    defer declared_program.deinit(allocator);
    const public_input = digest("recursive-v2-poseidon-input");
    const public_output = digest("recursive-v2-poseidon-output");
    const initial_state = try machineState(
        left_result.entry_cpu,
        segment_v2.snapshotDigest(left_result.rw_memory.words, .initial_word).id,
        digest("recursive-v2-io-entry"),
    );
    const shared_state = try machineState(
        left_result.exit_cpu,
        segment_v2.snapshotDigest(left_result.rw_memory.words, .final_word).id,
        digest("recursive-v2-io-shared"),
    );
    const final_state = try machineState(
        right_result.exit_cpu,
        segment_v2.snapshotDigest(right_result.rw_memory.words, .final_word).id,
        digest("recursive-v2-io-exit"),
    );
    const total_cycles = try std.math.add(
        u64,
        @intCast(left_result.cycle_count),
        @intCast(right_result.cycle_count),
    );
    const job = try span.JobContext.init(
        try span.CompleteExecution.init(
            protocol.PROTOCOL_ID_WORDS,
            scalarDigest(declared_program.tree.root),
            initial_state,
            final_state,
            public_input,
            public_output,
            total_cycles,
        ),
        2,
    );
    const left_span = try leafStatement(
        job,
        left_result,
        initial_state,
        shared_state,
        try span.EdgeClaim.present(public_input),
        span.EdgeClaim.absent(),
    );
    const left_source = try segment_v2.SourceV2.fromSegmentResult(
        digest("recursive-v2-session"),
        left_span,
        left_result,
    );
    const words = try encode(allocator, &left_source);
    defer allocator.free(words);
    const public_data = try frontend.air.public_data_v2.PublicDataV2.authenticate(
        words,
    );

    const native_lifecycle = if (comptime NativeEngine != Engine) NativeEngine.Backend.runtimeLifecycleSnapshot() else {};
    const native_telemetry = if (comptime NativeEngine != Engine) try NativeEngine.Backend.telemetrySnapshot() else {};
    var native_memory = @import("recursive_segment_v2_outer_engine.zig").ProducerAllocator{};
    defer std.debug.assert(native_memory.isEmpty());
    const native_allocator = native_memory.allocator();
    var probe = @import("recursive_segment_v2_native_profile.zig").Probe.init(allocator);
    defer probe.deinit();
    var prove_timer = try std.time.Timer.start();
    var output = try prover.proveRiscVSegmentV2WithEngine(
        NativeEngine,
        native_allocator,
        test_config,
        left_result,
        probe.recorder(),
        public_data,
    );
    const prove_ns = prove_timer.read();
    var native_output_owned = true;
    defer if (native_output_owned) output.deinit(native_allocator);
    try probe.finish();
    if (comptime NativeEngine != Engine) {
        const after = NativeEngine.Backend.runtimeLifecycleSnapshot();
        if (!after.initialized or !std.meta.eql(after.identity, native_lifecycle.identity) or
            after.initialization_count != native_lifecycle.initialization_count or
            after.shutdown_count != native_lifecycle.shutdown_count)
            return error.NativeMetalRuntimeChanged;
        const delta = (try NativeEngine.Backend.telemetrySnapshot()).delta(native_telemetry);
        try delta.requireMetalDispatch();
        if (delta.counters.metal_poseidon2_merkle_commits == 0)
            return error.NativeMetalPoseidonDispatchMissing;
        if (after.active_call_leases != 0) return error.NativeMetalActiveCallLeak;
        std.debug.print(
            "SEGMENT_V2_NATIVE_METAL device_dispatches={d} poseidon_commits={d} " ++
                "host_fallbacks={d} native_prove_ns={d} resident_resources_before_shutdown={d}\n",
            .{ delta.counters.metalDispatchTotal(), delta.counters.metal_poseidon2_merkle_commits, delta.counters.cpuFallbackTotal(), prove_ns, after.live_resident_resources },
        );
        // Proof bytes and public inputs are host-owned. Shut down the device
        // before fresh CPU decoding/verification and CPU outer construction.
        // Shutdown releases runtime-owned reusable scratch first and fails
        // if any proof-owned resident resource remains live.
        try NativeEngine.Backend.shutdown();
        const released = NativeEngine.Backend.runtimeLifecycleSnapshot();
        if (released.initialized or released.active_call_leases != 0 or released.live_resident_resources != 0)
            return error.NativeMetalResidentOwnerLeak;
    }

    // Exercise the exact external-ingress chain before any allocating decoder
    // sees the native proof: authenticated V2 statement -> allocation-free
    // shape walk -> fresh owned proof. The verifier consumes only that decoded
    // value, never the prover's in-memory proof object.
    var proof_bytes: std.ArrayList(u8) = .empty;
    defer proof_bytes.deinit(allocator);
    try postcard.serializeProof(
        Engine.Hasher,
        proof_bytes.writer(allocator),
        output.proof,
    );
    // The statement's canonical wire is caller-owned (`words` above). The
    // fixed-capacity claim contains only arrays/scalars and is copied directly
    // into verifier-owned heap storage, avoiding a multi-megabyte stack value.
    const native_statement = output.statement;
    if (native_statement.public_data.canonical_words.ptr != words.ptr or
        native_statement.public_data.canonical_words.len != words.len)
        return error.NativeStatementOwnerMismatch;
    const native_claim = try allocator.create(@TypeOf(output.interaction_claim.*));
    defer allocator.destroy(native_claim);
    @memcpy(std.mem.asBytes(native_claim), std.mem.asBytes(output.interaction_claim));
    output.deinit(native_allocator);
    native_output_owned = false;
    try native_memory.requireEmpty();
    std.debug.print(
        "SEGMENT_V2_NATIVE_MEMORY backend={s} scope=caller_allocator_payload excludes=size_routed_mmap_and_device producer_peak_bytes={d} producer_live_bytes_after_destroy={d} canonical_proof_bytes={d}\n",
        .{ if (comptime NativeEngine == Engine) "cpu" else "metal", native_memory.peakBytes(), native_memory.snapshot().active_bytes, proof_bytes.items.len },
    );
    try recursion.proof_ingress.validateV2ForVerifierConfig(
        proof_bytes.items,
        &native_statement,
        test_config,
        proof_bytes.items.len,
    );
    try std.testing.expectError(
        error.ProofResourceLimitExceeded,
        recursion.proof_ingress.validateV2ForVerifierConfig(
            proof_bytes.items,
            &native_statement,
            test_config,
            proof_bytes.items.len - 1,
        ),
    );
    var bad_statement = native_statement;
    bad_statement.authority_id[0] +%= 1;
    try std.testing.expectError(
        error.InvalidStatement,
        recursion.proof_ingress.validateV2ForVerifierConfig(
            proof_bytes.items,
            &bad_statement,
            test_config,
            proof_bytes.items.len,
        ),
    );
    var proof_stream = std.io.fixedBufferStream(proof_bytes.items);
    var decoded_proof = try postcard.deserializeProof(
        Engine.Hasher,
        allocator,
        proof_stream.reader(),
    );
    var decoded_proof_moved = false;
    defer if (!decoded_proof_moved) decoded_proof.deinit(allocator);
    try std.testing.expectEqual(proof_bytes.items.len, proof_stream.pos);

    var capture: subject.NativeCapture = undefined;
    var verifier_channel = Engine.Channel{};
    decoded_proof_moved = true;
    var verify_timer = try std.time.Timer.start();
    try prover.verifyRiscVSegmentV2WithEngineUsingChannelAndCapture(
        Engine,
        allocator,
        test_config,
        native_statement,
        decoded_proof,
        native_claim,
        &verifier_channel,
        &capture,
    );
    const verify_ns = verify_timer.read();
    var preparation_timer = try std.time.Timer.start();
    var capture_moved = false;
    defer if (!capture_moved) capture.deinit(allocator);
    try capture.validate();

    var profile = try recursion.captured_fri.Owned.init(
        allocator,
        recursion.captured_fri.ProfileConfig.fromPcs(test_config),
        &capture.proof,
    );
    defer profile.deinit();
    if (profile.trace_tree_heights.len != recursion.fixed_profile.TREE_COUNT)
        return error.InvalidProofShape;
    var tree_heights: [recursion.fixed_profile.TREE_COUNT]u32 = undefined;
    @memcpy(&tree_heights, profile.trace_tree_heights);
    const shape = try recursion.transcript_shape.derive(
        profile.circuit.profile(),
        tree_heights,
        .{
            .sampled_value_count = profile.sampled_value_count,
            .queried_values_per_query = profile.queried_values_per_query,
            .claimed_sum_count = profile.claimed_sum_count,
            .interaction_pow_bits = profile.interaction_pow_bits,
            .pcs_pow_bits = profile.pcs_pow_bits,
        },
    );
    var vm_plan = try schedule.Plan.initShape(
        allocator,
        try schedule.vmProgramSpec(0, 0),
        shape,
    );
    defer vm_plan.deinit();
    var recursion_plan = try schedule.Plan.initShape(
        allocator,
        schedule.RECURSION_PROGRAM_SPEC_V1,
        shape,
    );
    defer recursion_plan.deinit();
    const keys = try recursion.segment_leaf_authority_v2.VerifierKeyAuthorityV2.init(
        digest("recursive-v2-segment-vk"),
        digest("recursive-v2-parent-vk"),
    );
    var bundle = try subject.PreparedNativeV2LeafOuter.init(
        allocator,
        allocator,
        &capture,
        test_config,
        native_claim.interaction_pow,
        keys,
        recursion.air.universal_challenges.UniversalRelations.dummy(),
        .{ .vm = &vm_plan, .recursion = &recursion_plan },
    );
    capture_moved = true;
    defer bundle.deinit();
    try bundle.validate();
    const preparation_ns = preparation_timer.read();
    if (comptime !full_regression) {
        std.debug.print(
            "\nSEGMENT_V2_LADDER_NATIVE requested_steps={d} retired_cycles={d} " ++
                "continuation_cycles={d} trace_rows={d} native_backend={s} native_queries={d} outer_queries={d} " ++
                "native_pcs_pow_bits={d} outer_pcs_pow_bits={d} program={s} memory_addresses={d} " ++
                "native_prove_ms={d:.3} native_verify_ms={d:.3} " ++
                "recursive_prepare_ms={d:.3} native_proof_bytes={d} native_tree_heights={any}\n",
            .{
                native_steps,
                left_result.cycle_count,
                right_result.cycle_count,
                left_result.execution_trace.rows.items.len,
                if (comptime NativeEngine == Engine) "cpu" else "metal",
                test_config.fri_config.n_queries,
                @import("recursive_segment_v2_outer_engine.zig").OUTER_CONFIG.fri_config.n_queries,
                test_config.pow_bits,
                @import("recursive_segment_v2_outer_engine.zig").OUTER_CONFIG.pow_bits,
                if (memory_addresses != null) "lw_addi_sw_updates" else "finite_addi_bne_counter_loop",
                memory_addresses orelse 0,
                milliseconds(prove_ns),
                milliseconds(verify_ns),
                milliseconds(preparation_ns),
                proof_bytes.items.len,
                tree_heights,
            },
        );
        try Hook.run(allocator, &bundle);
        return;
    }
    try std.testing.expectEqual(@as(u8, 18), bundle.rows_18_34_core.first_row);
    try std.testing.expectEqual(@as(u8, 34), bundle.rows_18_34_core.last_row);
    try std.testing.expectEqual(@as(u8, 17), bundle.rows_18_34_core.row_count);
    try std.testing.expect(bundle.rows_18_34_core.core_poseidon_call_count > 0);
    try std.testing.expect(!bundle.rows_18_34_core.productionReady());
    try std.testing.expect(!bundle.rows0Through9Publishable());
    try std.testing.expect(!bundle.exact47DomainClosureVerified());
    try std.testing.expect(!bundle.productionReady());
    try std.testing.expectEqual(
        bundle.transcript_execution.poseidonCalls().len,
        try bundle.shared_poseidon_layout.transcript.count(),
    );
    try std.testing.expectEqual(
        try bundle.authority_prepared.authorityPoseidonCallCount(),
        try bundle.shared_poseidon_layout.statement_authority.count(),
    );

    try std.testing.expectEqual(
        @as(usize, 0),
        try bundle.shared_poseidon_layout.verifier_core.count(),
    );
    // Physical lookup activation adds one header frame (3 permutations) and
    // three SHA-256 identity frames (4 each) to the old 885-call transcript.
    try std.testing.expectEqual(
        @as(usize, 900),
        try bundle.shared_poseidon_layout.transcript.count(),
    );
    try std.testing.expectEqual(
        @as(usize, 14),
        try bundle.shared_poseidon_layout.statement_authority.count(),
    );
    try std.testing.expect(!bundle.shared_poseidon_layout.call_set_complete);

    // Exact tuple closure does not need the leaf fixture's repeated core
    // reconstructions, mutation fleet, or non-core tree publication. Retain
    // the expensive real native proof and verified-capture custody above,
    // then let an explicitly capable hook classify the authenticated 38-row
    // cohort directly. This is opt-in development plumbing, never a release
    // proof shortcut.
    if (comptime @hasDecl(Hook, "runTupleClosureDiagnostic")) {
        if (std.process.hasEnvVarConstant(TUPLE_CLOSURE_DIAGNOSTIC_ENV)) {
            try Hook.runTupleClosureDiagnostic(allocator, &bundle);
            return;
        }
    }

    const saved_call = bundle.row34_boundary_prefix_calls[0].input[0];
    bundle.row34_boundary_prefix_calls[0].input[0] +%= 1;
    try std.testing.expectError(error.CallLayoutMismatch, bundle.validate());
    bundle.row34_boundary_prefix_calls[0].input[0] = saved_call;
    try bundle.validate();

    const saved_core_identity = bundle.rows_18_34_core.identity;
    bundle.rows_18_34_core.identity[0] ^= 1;
    try std.testing.expectError(
        error.V2CoreRows18Through34PreflightMismatch,
        bundle.validate(),
    );
    bundle.rows_18_34_core.identity = saved_core_identity;
    try bundle.validate();

    // Turn the authenticated boundary prefix into the concrete native-leaf
    // verifier cohort. The owner is heap-stable at the integration boundary;
    // its in-place initializer still exercises the audited move-safe return
    // path internally, which protects ReleaseFast from stale stack pointers.
    const source_preflight = try @import("recursive_segment_v2_noncore_owner.zig")
        .PreflightV2.init(&bundle);
    var public_native_relations = @import("recursive_segment_v2_noncore_owner.zig")
        .nativeRelations(&bundle);
    const public_native_inputs = @import("recursive_segment_v2_noncore_owner.zig")
        .publicInputs(&bundle, &public_native_relations);
    var public_native_sum_source = try recursion
        .segment_public_native_sum_authority_v2.SourceV2.init(
        allocator,
        &source_preflight.public_prepared,
        public_native_inputs,
    );
    defer public_native_sum_source.deinit();
    var public_native_sum_evaluation = try recursion
        .segment_public_native_sum_authority_v2.OwnedEvaluationV2.init(
        allocator,
        &public_native_sum_source,
        &source_preflight.public_prepared,
        public_native_inputs,
    );
    defer public_native_sum_evaluation.deinit();
    const core_inputs = core_outer.NativeSegmentCoreAuthorityInputsV2{
        .captured = &bundle.captured_fri,
        .vm_air = .{ .borrowed = &bundle.vm_air },
        .transcript_prepared = &source_preflight.transcript_prepared,
        .transcript_program = &bundle.transcript_program,
        .transcript_execution = &bundle.transcript_execution,
        .transcript_plan = &bundle.vm_plan,
        .public_native_sum_source = &public_native_sum_source,
        .public_native_sum_evaluation = &public_native_sum_evaluation,
        .verifier_plans = .{
            .vm = &bundle.vm_plan,
            .recursion = &bundle.recursion_plan,
        },
        .boundary_layout = &bundle.shared_poseidon_layout,
        .boundary_calls = bundle.row34_boundary_prefix_calls,
    };
    var core_init_timer = try std.time.Timer.start();
    const native_core = try allocator.create(core_outer.NativeSegmentCoreV2);
    core_outer.NativeSegmentCoreV2.initInPlace(
        native_core,
        allocator,
        core_inputs,
    ) catch |err| {
        allocator.destroy(native_core);
        return err;
    };
    const core_init_ns = core_init_timer.read();
    std.debug.print(
        "\nV2_NATIVE_CORE_STAGE stage=core_init elapsed_ms={d:.3}\n",
        .{milliseconds(core_init_ns)},
    );
    defer {
        native_core.deinit();
        allocator.destroy(native_core);
    }

    try native_core.validateCoreReady();
    try std.testing.expectError(
        error.V2CoreCohortMismatch,
        native_core.validateComplete(),
    );
    const core_calls = try native_core.corePoseidonCalls();
    const complete_calls = try native_core.completePoseidonCalls();
    try std.testing.expectEqual(
        @as(usize, bundle.rows_18_34_core.core_poseidon_call_count),
        core_calls.len,
    );
    try std.testing.expectEqual(@as(usize, 294), core_calls.len);
    try std.testing.expectEqual(
        bundle.row34_boundary_prefix_calls.len + core_calls.len,
        complete_calls.len,
    );
    try std.testing.expectEqual(@as(usize, 1_208), complete_calls.len);
    const complete_layout = try native_core.completeScheduleReceipt();
    try std.testing.expect(complete_layout.call_set_complete);
    try std.testing.expect(complete_layout.verifier_core_range_populated);
    try std.testing.expect(std.meta.eql(
        bundle.shared_poseidon_layout.transcript,
        complete_layout.transcript,
    ));
    try std.testing.expect(std.meta.eql(
        bundle.shared_poseidon_layout.statement_authority,
        complete_layout.statement_authority,
    ));
    try std.testing.expectEqual(core_calls.len, try complete_layout.verifier_core.count());
    const logs = try native_core.componentLogSizes();
    const expected_provider_log: u32 = @intCast(@max(
        @as(usize, 1),
        std.math.log2_int_ceil(usize, complete_calls.len),
    ));
    try std.testing.expectEqual(
        expected_provider_log,
        logs[core_outer.NATIVE_V2_CORE_ROW_COUNT - 1],
    );
    try std.testing.expectEqual(@as(u32, 11), expected_provider_log);

    var provider_timer = try std.time.Timer.start();
    try native_core.finalizeSharedProviderMain();
    const provider_ns = provider_timer.read();
    std.debug.print(
        "V2_NATIVE_CORE_STAGE stage=provider elapsed_ms={d:.3}\n",
        .{milliseconds(provider_ns)},
    );
    try native_core.validateComplete();
    try std.testing.expectError(
        error.V2CoreCohortMismatch,
        native_core.finalizeSharedProviderMain(),
    );

    const provider_relations = try recursion.air.universal_shared_provider
        .SharedProviderRelations.init(&bundle.outer_relations);
    var interaction_timer = try std.time.Timer.start();
    const generated = try native_core.prepareInteractions(
        allocator,
        &bundle.outer_relations,
        &provider_relations,
    );
    const interaction_ns = interaction_timer.read();
    std.debug.print(
        "V2_NATIVE_CORE_STAGE stage=interaction elapsed_ms={d:.3}\n",
        .{milliseconds(interaction_ns)},
    );
    try generated.validateAgainst(
        native_core,
        &bundle.outer_relations,
        &provider_relations,
    );
    var independent_timer = try std.time.Timer.start();
    const independently_generated =
        try core_outer.independentlyRebuildNativeSegmentCoreV2(
            allocator,
            core_inputs,
            &bundle.outer_relations,
            &provider_relations,
        );
    const independent_ns = independent_timer.read();
    std.debug.print(
        "V2_NATIVE_CORE_STAGE stage=independent elapsed_ms={d:.3}\n",
        .{milliseconds(independent_ns)},
    );
    try std.testing.expectEqualSlices(
        u8,
        &generated.identity,
        &independently_generated.identity,
    );
    try std.testing.expect(std.meta.eql(
        generated.claims,
        independently_generated.claims,
    ));
    try std.testing.expect(std.meta.eql(
        generated.audits,
        independently_generated.audits,
    ));

    // Exercise the complementary 21-row owner against this same successful
    // capture. Its helper owns only functional non-core validation; the
    // external hook below is the sole continuation allowed to spend time on
    // the aggregate 38-row STARK.
    try noncore_gate.runPrepared(allocator, &bundle);

    // This is deliberately the final fallible authority boundary before the
    // optional complete-outer-proof continuation. The hook receives only the
    // same verified, owned prepared leaf used above; no detached claims,
    // schedules, rows, or prover-side receipts cross this seam.
    try Hook.run(allocator, &bundle);

    std.debug.print(
        "\nV2_POSEIDON_RECURSIVE_INGRESS cycles={d} prove_ms={d:.3} " ++
            "verify_ms={d:.3} transcript_calls={d} authority_calls={d} " ++
            "core_calls={d} proof_bytes={d} core_cols={d}/{d}/{d} " ++
            "core_constraints={d} complete_provider_calls={d} " ++
            "complete_provider_log={d} core_init_ms={d:.3} " ++
            "provider_ms={d:.3} interaction_ms={d:.3} " ++
            "independent_ms={d:.3}\n",
        .{
            left_result.cycle_count,
            milliseconds(prove_ns),
            milliseconds(verify_ns),
            bundle.transcript_execution.poseidonCalls().len,
            try bundle.authority_prepared.authorityPoseidonCallCount(),
            bundle.rows_18_34_core.core_poseidon_call_count,
            proof_bytes.items.len,
            bundle.rows_18_34_core.preprocessed_columns,
            bundle.rows_18_34_core.main_columns,
            bundle.rows_18_34_core.interaction_columns,
            bundle.rows_18_34_core.constraint_count,
            complete_calls.len,
            expected_provider_log,
            milliseconds(core_init_ns),
            milliseconds(provider_ns),
            milliseconds(interaction_ns),
            milliseconds(independent_ns),
        },
    );
}

/// Builds two genuinely adjacent SegmentV2 leaves from one execution session
/// and crosses each through the native prove -> serialize -> preflight ->
/// decode -> independent verify -> owned recursive-ingress transaction.  The
/// hook observes the prepared leaves only after both verifier captures are
/// complete.  No duplicated child, synthetic publication, or detached claim
/// can enter a temporal-parent proof through this harness.
pub fn runTemporalPairGateWithHook(
    allocator: std.mem.Allocator,
    comptime Hook: type,
) !void {
    comptime {
        if (!@hasDecl(Hook, "run"))
            @compileError("temporal V2 pair hook must declare run");
        @import("stwo_prover_api").assertProverEngine(Engine);
        if (Engine.Channel != recursion.poseidon2_channel.Channel or
            Engine.Hasher != recursion.poseidon2_channel.MerkleHasher or
            Engine.Channel == recursion.native_scheduled_channel.Channel)
        {
            @compileError("temporal V2 pair gate must use generic Poseidon2");
        }
    }

    // Two real adjacent LUI executions with the same verifier profile; the
    // second segment then reaches the terminal self-loop. Keeping the opcode
    // family fixed makes this gate exercise
    // temporal custody rather than the separately tracked variable-profile
    // SegmentV2 publication-input extension.
    const elf = frontend.testing.guest_precompile_test_elf.buildTemporalPair();
    var session = try runner.Poseidon2ExecutionSession.init(allocator, &elf, .{});
    defer session.deinit();
    var left_profile = try session.startSegment(1);
    defer left_profile.deinit();
    const left_result = &left_profile.base;
    var right_profile = try session.resumeSegment(left_result.continuation.?, 16);
    defer right_profile.deinit();
    const right_result = &right_profile.base;

    var declared_program = try frontend.air.program.commitment.buildDeclared(
        allocator,
        left_result.execution_trace.rows.items,
        left_result.rw_memory.program_words,
        null,
    );
    defer declared_program.deinit(allocator);
    const public_input = digest("recursive-v2-poseidon-input");
    const public_output = digest("recursive-v2-poseidon-output");
    const initial_state = try machineState(
        left_result.entry_cpu,
        segment_v2.snapshotDigest(left_result.rw_memory.words, .initial_word).id,
        digest("recursive-v2-io-entry"),
    );
    const shared_state = try machineState(
        left_result.exit_cpu,
        segment_v2.snapshotDigest(left_result.rw_memory.words, .final_word).id,
        digest("recursive-v2-io-shared"),
    );
    const right_entry_state = try machineState(
        right_result.entry_cpu,
        segment_v2.snapshotDigest(right_result.rw_memory.words, .initial_word).id,
        digest("recursive-v2-io-shared"),
    );
    if (!std.meta.eql(shared_state, right_entry_state))
        return error.InvalidTemporalBoundary;
    const final_state = try machineState(
        right_result.exit_cpu,
        segment_v2.snapshotDigest(right_result.rw_memory.words, .final_word).id,
        digest("recursive-v2-io-exit"),
    );
    const total_cycles = try std.math.add(
        u64,
        @intCast(left_result.cycle_count),
        @intCast(right_result.cycle_count),
    );
    const job = try span.JobContext.init(
        try span.CompleteExecution.init(
            protocol.PROTOCOL_ID_WORDS,
            scalarDigest(declared_program.tree.root),
            initial_state,
            final_state,
            public_input,
            public_output,
            total_cycles,
        ),
        2,
    );
    const statements = [2]span.SpanStatement{
        try leafStatement(
            job,
            left_result,
            initial_state,
            shared_state,
            try span.EdgeClaim.present(public_input),
            span.EdgeClaim.absent(),
        ),
        try leafStatement(
            job,
            right_result,
            shared_state,
            final_state,
            span.EdgeClaim.absent(),
            try span.EdgeClaim.present(public_output),
        ),
    };
    const keys = try recursion.segment_leaf_authority_v2.VerifierKeyAuthorityV2.init(
        digest("recursive-v2-segment-vk"),
        digest("recursive-v2-parent-vk"),
    );

    var left = try prepareTemporalNativeLeaf(
        allocator,
        left_result,
        statements[0],
        keys,
    );
    defer left.deinit();
    var right = try prepareTemporalNativeLeaf(
        allocator,
        right_result,
        statements[1],
        keys,
    );
    defer right.deinit();
    if (std.mem.eql(u8, &left.identity, &right.identity))
        return error.DuplicateTemporalLeaf;

    try Hook.run(allocator, &left, &right);
}

