src/integrations/riscv_cpu/recursive_tem:
//! Real authenticated temporal `2 -> 1` parent proof.
//!
//! This gate deliberately begins with two distinct adjacent native SegmentV2
//! executions.  Each child crosses the native prove/serialize/preflight/
//! decode/verify-with-capture boundary, then receives its own independently
//! verified 39-row outer proof.  Only verifier-minted publications and
//! captures enter the temporal pair, row-18 recorder authority, and complete
//! rows-0--35 parent transaction below.

const std = @import("std");
const frontend = @import("stwo_riscv_frontend");
const integration = @import("stwo_riscv_cpu_integration");

const ingress = @import("recursive_segment_v2_leaf_outer_proof_test.zig");
const outer_proof = @import("recursive_segment_v2_outer_proof_test.zig");
const recording_support = @import("recursive_v3_recording_test_support.zig");

const leaf_outer = @import("recursive_segment_v2_leaf_outer.zig");
const outer_cohort = @import("recursive_segment_v2_outer_cohort.zig");
const outer_engine = @import("recursive_segment_v2_outer_engine.zig");
const child_authority =
    @import("recursive_segment_v2_temporal_child_authority.zig");
const pair_authority = @import("recursive_temporal_pair_authority_v2.zig");
const prefix_runtime = @import("recursive_temporal_parent_prefix_runtime.zig");
const row18_source = @import("recursive_temporal_parent_row18_source_v3.zig");
const temporal_cohort = @import("recursive_temporal_parent_cohort_v3.zig");
const temporal_manifest = @import("recursive_temporal_parent_manifest_v3.zig");
const temporal_nonfri = @import("recursive_temporal_nonfri_source_v2.zig");
const level2_composition =
    @import("recursive_temporal_level2_composition_v1.zig");
const binary_driver = integration.recursive_binary_outer;
const binary_cohort_mod = integration.recursive_binary_outer_cohort;

const recursion = frontend.recursion;
const universal = recursion.air.universal_challenges;
const shared_provider = recursion.air.universal_shared_provider;
const composition_v3 = recursion.recursion_air_composition_circuit_v3;
const binary_fixture = frontend.testing.binary_pair_outer_fixture;

const BinaryCohort = binary_cohort_mod.Cohort(
    binary_fixture.CHILD_DIMENSIONS,
    binary_fixture.STATEMENT_DIMENSIONS,
);
const ParentKernel = binary_driver.NativeEngineKernelForManifest(
    temporal_cohort.Cohort,
    temporal_manifest,
);

pub fn runGate(allocator: std.mem.Allocator) !void {
    return ingress.runTemporalPairGateWithHook(allocator, RealParentHook);
}

const RealParentHook = struct {
    pub fn run(
        allocator: std.mem.Allocator,
        left_prepared: *const leaf_outer.PreparedNativeV2LeafOuter,
        right_prepared: *const leaf_outer.PreparedNativeV2LeafOuter,
    ) !void {
        return proveTemporalParentWithConsumer(
            allocator,
            left_prepared,
            right_prepared,
            DefaultParentConsumer{},
        );
    }
};

const DefaultParentConsumer = struct {
    fn consume(
        _: DefaultParentConsumer,
        _: *const ParentKernel.VerifiedPublicationV1,
        _: *const ParentKernel.VerifiedArtifactV1,
        _: *binary_driver.OuterProofCapture,
        _: *level2_composition.CaptureV1,
        _: binary_driver.Receipt,
    ) !bool {
        return false;
    }
};

pub fn proveTemporalParentWithConsumer(
    allocator: std.mem.Allocator,
    left_prepared: *const leaf_outer.PreparedNativeV2LeafOuter,
    right_prepared: *const leaf_outer.PreparedNativeV2LeafOuter,
    consumer: anytype,
) !void {
    if (left_prepared == right_prepared or std.mem.eql(
        u8,
        &left_prepared.identity,
        &right_prepared.identity,
    )) return error.DuplicateTemporalLeaf;

    std.debug.print(
        "\nTEMPORAL_CHILD_GEOMETRY left={d}/{d}:{d}/{d}:{d}/{d} " ++
            "right={d}/{d}:{d}/{d}:{d}/{d}\n",
        .{
            left_prepared.authority_prepared.authority_hash_plan.component_count,
            left_prepared.capture.vm_air.component_descs.len,
            left_prepared.authority_prepared.authority_hash_plan.infra_count,
            left_prepared.capture.vm_air.infra_descs.len,
            left_prepared.capture.vm_air.detailed_claims.len,
            left_prepared.capture.vm_air.profile.claimed_sum_count,
            right_prepared.authority_prepared.authority_hash_plan.component_count,
            right_prepared.capture.vm_air.component_descs.len,
            right_prepared.authority_prepared.authority_hash_plan.infra_count,
            right_prepared.capture.vm_air.infra_descs.len,
            right_prepared.capture.vm_air.detailed_claims.len,
            right_prepared.capture.vm_air.profile.claimed_sum_count,
        },
    );

    var left = try outer_proof.provePreparedNativeLeaf(
        outer_cohort.Cohort,
        allocator,
        left_prepared,
        left_prepared,
        outer_engine.ExecutionOptions{ .worker_count = 1 },
    );
    defer left.capture.deinit(allocator);
    var right = try outer_proof.provePreparedNativeLeaf(
        outer_cohort.Cohort,
        allocator,
        right_prepared,
        right_prepared,
        outer_engine.ExecutionOptions{ .worker_count = 1 },
    );
    defer right.capture.deinit(allocator);
    try left.publication.validate();
    try right.publication.validate();
    if (std.meta.eql(
        left.publication.publication_id,
        right.publication.publication_id,
    )) return error.DuplicateTemporalLeaf;

    // The manifest and finalized constraint graph are profile authority,
    // not child-witness authority.  One fresh cohort supplies their stable
    // storage while both child artifacts remain separately re-admitted.
    var segment_cohort = outer_cohort.Cohort.init(
        allocator,
        left_prepared,
    ) catch |err| return stageFailure("segment_cohort", err);
    defer segment_cohort.deinit();
    var right_segment_cohort = outer_cohort.Cohort.init(
        allocator,
        right_prepared,
    ) catch |err| return stageFailure("right_segment_cohort", err);
    defer right_segment_cohort.deinit();
    std.debug.print(
        "\nTEMPORAL_CHILD_MANIFEST left_match={} right_match={} " ++
            "same_publication_manifest={}\n",
        .{
            std.mem.eql(
                u8,
                &segment_cohort.manifest().seal,
                &left.publication.manifest_sha_id,
            ),
            std.mem.eql(
                u8,
                &segment_cohort.manifest().seal,
                &right.publication.manifest_sha_id,
            ),
            std.mem.eql(
                u8,
                &left.publication.manifest_sha_id,
                &right.publication.manifest_sha_id,
            ),
        },
    );
    reportManifestDiff(
        segment_cohort.manifest(),
        right_segment_cohort.manifest(),
    );

    var left_child: child_authority.PreparedTemporalChildV1 = undefined;
    try child_authority.admitInto(&left_child, &left.publication);
    var right_child: child_authority.PreparedTemporalChildV1 = undefined;
    try child_authority.admitInto(&right_child, &right.publication);
    const root_pin = recursion.temporal_pair_node.RootVkPinV2{
        .expected_aggregator_vk_id = left.publication.recursive_parent_vk_id,
    };
    var pair: pair_authority.PreparedTemporalPairAuthorityV1 = undefined;
    try pair_authority.prepareInto(
        &pair,
        &left_child,
        &right_child,
        &root_pin,
    );
    try pair.validate();

    const artifacts = binary_driver.TemporalParentArtifactViewV1.init(
        .{
            .publication = &left.publication,
            .capture = &left.capture,
            .recursive_witness = &left.recursive_witness,
        },
        .{
            .publication = &right.publication,
            .capture = &right.capture,
            .recursive_witness = &right.recursive_witness,
        },
        .{
            segment_cohort.manifest(),
            right_segment_cohort.manifest(),
        },
        &pair,
    ) catch |err| return stageFailure("artifact_view", err);
    const runtime = prefix_runtime.RuntimeInputsV1{
        .artifacts = &artifacts,
        .prepared_leaves = .{ left_prepared, right_prepared },
    };
    _ = try runtime.validate();

    // Record the SegmentV2 verifier graph once.  Claims used to construct
    // these adapters come from the left verifier transaction; the graph
    // itself is witness-independent and row18 independently evaluates it
    // for both authenticated children below.
    const segment_relations = universal.UniversalRelations.fromDraws(
        &left.recursive_witness.relation_draws,
    );
    try segment_relations.validate();
    const segment_provider_relations =
        try shared_provider.SharedProviderRelations.init(
            &segment_relations,
        );
    const segment_generated =
        segment_cohort.rebuildGeneratedInteractions(
            &segment_relations,
            &segment_provider_relations,
        ) catch |err| return stageFailure("segment_interactions", err);
    var segment_components = segment_cohort.initComponents(
        &segment_generated,
        &segment_relations,
        &segment_provider_relations,
    ) catch |err| return stageFailure("segment_components", err);
    defer segment_components.deinit();

    var fixture = try binary_fixture.Fixture.init(allocator);
    defer fixture.deinit();
    const binary_inputs = BinaryCohort.AuthorityInputs{
        .non_fri = try fixture.nonFriInputs(),
        .fri_source = fixture.friSource(),
    };
    var universal_cohort = try BinaryCohort.init(
        allocator,
        binary_inputs,
    );
    defer universal_cohort.deinit();
    var binary_channel = binary_driver.Engine.Channel{};
    const binary_relations = try universal.UniversalRelations.draw(
        allocator,
        &binary_channel,
    );
    const binary_provider_relations =
        try shared_provider.SharedProviderRelations.init(
            &binary_relations,
        );
    const binary_generated =
        try universal_cohort.rebuildGeneratedInteractions(
            &binary_relations,
            &binary_provider_relations,
        );
    var binary_components = try universal_cohort.initComponents(
        &binary_generated,
        &binary_relations,
        &binary_provider_relations,
    );
    defer binary_components.deinit();

    var arena = std.heap.ArenaAllocator.init(allocator);
    defer arena.deinit();
    const binary_capture = try recording_support.syntheticCapture(
        arena.allocator(),
        universal_cohort.manifest(),
        8_301,
    );
    const manifests = composition_v3.TrustedManifestsV3{
        .universal = universal_cohort.manifest(),
        .segment = segment_cohort.manifest(),
    };
    const air_program_ids = composition_v3.AirProgramIdsV3{
        .segment_leaf = left.publication.air_program_id,
        .binary_node = recording_support.nativeDigest(8_401),
        .empty_leaf = recording_support.nativeDigest(8_501),
    };
    const session = try composition_v3.HeterogeneousSessionV3.create(
        allocator,
        manifests,
        air_program_ids,
        &left.capture,
        &binary_capture,
    );
    var session_live = true;
    defer if (session_live) session.deinit();
    try session.recordPrograms(
        &segment_components,
        &binary_components,
        &binary_components,
    );
    const recording = try session.finish();
    session_live = false;
    defer recording.deinit();

    const row18 = row18_source.Row18AuthorityV3.init(
        allocator,
        runtime,
        recording,
        manifests,
        air_program_ids,
    ) catch |err| return stageFailure("row18_authority", err);
    defer row18.deinit();
    try row18.validateAgainst(runtime);

    var parent_preflight = temporal_cohort.Cohort.init(
        allocator,
        .{ .runtime = runtime, .row18 = row18 },
    ) catch |err| return stageFailure("parent_cohort_init", err);
    defer parent_preflight.deinit();
    parent_preflight.validate() catch |err|
        return stageFailure("parent_cohort_validate", err);

    var parent_capture: binary_driver.OuterProofCapture = undefined;
    var parent_capture_owned = true;
    defer if (parent_capture_owned) parent_capture.deinit(allocator);
    var parent_publication: ParentKernel.VerifiedPublicationV1 = undefined;
    var parent_artifact: ParentKernel.VerifiedArtifactV1 = undefined;
    const receipt = ParentKernel.proveAndVerifyWithExecutionAndArtifact(
        allocator,
        .{ .runtime = runtime, .row18 = row18 },
        .{ .worker_count = 1 },
        &parent_capture,
        &parent_publication,
        &parent_artifact,
    ) catch |err| return stageFailure("parent_prove_verify", err);
    try parent_publication.validate();
    try parent_artifact.validateAgainst(&parent_publication);
    try parent_artifact.recursive_admission.validateAgainst(&parent_capture);
    var parent_composition = level2_composition.CaptureV1.init(
        allocator,
        &parent_preflight,
        &parent_capture,
        &parent_publication,
        &parent_artifact,
    ) catch |err| return stageFailure("parent_composition_capture", err);
    var parent_composition_owned = true;
    defer if (parent_composition_owned) parent_composition.deinit();
    const recursive_geometry = try recursion.outer_parent_child_admission
        .deriveAdmission(
        &parent_artifact.recursive_admission.receipt,
        &parent_capture,
    );
    _ = try temporal_nonfri.outerScheduleShapeForClaimCount(
        &parent_capture,
        temporal_manifest.COMPONENT_COUNT,
    );
    std.debug.print(
        "TEMPORAL_PARENT_WIRE_DIMENSIONS commitments={d} claims={d} " ++
            "samples={d} queried={d} paths={d} fri={d} queries={d} " ++
            "fold={d} coefficients={d} depth={d}\n",
        .{
            recursive_geometry.dimensions.commitment_count,
            recursive_geometry.dimensions.claimed_sum_count,
            recursive_geometry.dimensions.sampled_value_count,
            recursive_geometry.dimensions.queried_value_count,
            recursive_geometry.dimensions.trace_path_count,
            recursive_geometry.dimensions.fri_layer_count,
            recursive_geometry.dimensions.query_count,
            recursive_geometry.dimensions.maximum_fold_width,
            recursive_geometry.dimensions.last_layer_coefficient_count,
            recursive_geometry.dimensions.maximum_merkle_depth,
        },
    );
    try std.testing.expectEqual(
        parent_artifact.recursive_wire_bytes,
        try recursion.outer_parent_child_admission.runtimeCanonicalByteCount(
            parent_artifact.recursive_admission.seal,
            &parent_artifact.recursive_admission.receipt,
            &parent_capture,
        ),
    );
    try std.testing.expectEqual(
        parent_artifact.recursive_proof_id,
        try recursion.outer_parent_child_admission.proofIdRuntime(
            parent_artifact.recursive_admission.seal,
            &parent_artifact.recursive_admission.receipt,
            &parent_capture,
        ),
    );
    try std.testing.expect(temporal_cohort.COMPLETE_PARENT_PROOF_AVAILABLE);
    try std.testing.expect(temporal_cohort.TEMPORAL_PARENT_VERIFIED);
    try std.testing.expect(!temporal_cohort.PROTOCOL_SUBSTRATE_ONLY);
    try std.testing.expect(temporal_manifest.SUFFIX_SOURCE_AVAILABLE);
    try std.testing.expect(temporal_manifest.COMPLETE_PARENT_PROOF_AVAILABLE);
    try std.testing.expect(
        binary_driver.CURRENT_TEMPORAL_PARENT_CAPABILITIES.ready(),
    );
    try std.testing.expect(receipt.canonical_proof_bytes > 0);
    try std.testing.expect(receipt.prove_ns > 0);
    try std.testing.expect(receipt.verify_ns > 0);
    try std.testing.expectEqual(
        @as(u8, temporal_manifest.COMPONENT_COUNT),
        receipt.roster_count,
    );
    try std.testing.expect(parent_capture.commitments.len > 0);
    try std.testing.expect(parent_capture.queries.raw.len > 0);

    std.debug.print(
        "\nTEMPORAL_PARENT_REAL_PROOF bytes={d} prove_ms={d:.3} " ++
            "verify_ms={d:.3} rows={d} pair_poseidon={d}\n",
        .{
            receipt.canonical_proof_bytes,
            milliseconds(receipt.prove_ns),
            milliseconds(receipt.verify_ns),
            receipt.roster_count,
            receipt.pair_authentication_poseidon_permutations,
        },
    );
    const proof_sha256_hex = std.fmt.bytesToHex(
        receipt.canonical_proof_sha256,
        .lower,
    );
    const publication_sha256_hex = std.fmt.bytesToHex(
        parent_publication.publication_sha_id,
        .lower,
    );
    const cohort_authority_sha256_hex = std.fmt.bytesToHex(
        parent_publication.cohort_authority_sha_id,
        .lower,
    );
    const audit_sha256_hex = std.fmt.bytesToHex(
        parent_publication.audit_sha_id,
        .lower,
    );
    const closure_receipt_sha256_hex = std.fmt.bytesToHex(
        parent_publication.closure_receipt_sha_id,
        .lower,
    );
    std.debug.print(
        "TEMPORAL_PARENT_REAL_IDENTITIES proof_sha256={s} " ++
            "publication_sha256={s} cohort_authority_sha256={s} " ++
            "audit_sha256={s} closure_receipt_sha256={s}\n",
        .{
            &proof_sha256_hex,
            &publication_sha256_hex,
            &cohort_authority_sha256_hex,
            &audit_sha256_hex,
            &closure_receipt_sha256_hex,
        },
    );
    if (try consumer.consume(
        &parent_publication,
        &parent_artifact,
        &parent_capture,
        &parent_composition,
        receipt,
    )) {
        parent_capture_owned = false;
        parent_composition_owned = false;
    }
}

fn milliseconds(nanoseconds: u64) f64 {
    return @as(f64, @floatFromInt(nanoseconds)) / std.time.ns_per_ms;
}

fn stageFailure(stage: []const u8, err: anyerror) anyerror {
    std.debug.print(
        "\nTEMPORAL_PARENT_STAGE_FAIL stage={s} error={s}\n",
        .{ stage, @errorName(err) },
    );
    if (@errorReturnTrace()) |trace| std.debug.dumpStackTrace(trace.*);
    return err;
}

fn reportManifestDiff(left: anytype, right: @TypeOf(left)) void {
    for (left.placements, right.placements, 0..) |lhs, rhs, row| {
        if (std.meta.eql(lhs, rhs)) continue;
        const left_log = if (lhs) |placement| placement.geometry.log_size else 0;
        const right_log = if (rhs) |placement| placement.geometry.log_size else 0;
        std.debug.print(
            "TEMPORAL_CHILD_MANIFEST_DIFF row={d} log={d}/{d}\n",
            .{ row, left_log, right_log },
        );
    }
    std.debug.print(
        "TEMPORAL_CHILD_MANIFEST_AUTH transcript={} statement={} " ++
            "public={} boundary={}\n",
        .{
            std.meta.eql(
                left.transcript_manifest_id,
                right.transcript_manifest_id,
            ),
            std.meta.eql(
                left.statement_manifest_id,
                right.statement_manifest_id,
            ),
            std.meta.eql(left.public_manifest_id, right.public_manifest_id),
            std.meta.eql(
                left.boundary_manifest_id,
                right.boundary_manifest_id,
            ),
        },
    );
}

test "real authenticated temporal SegmentV2 2-to-1 parent independently verifies" {
    try runGate(std.testing.allocator);
}

src/integrations/riscv_cpu/recursive_par:
//! Exact-type and fail-atomic gate for the CPU parent-statement adapter.

const std = @import("std");
const integration = @import("stwo_riscv_cpu_integration");
const frontend = @import("stwo_riscv_frontend");

const recursion = frontend.recursion;
const admission = recursion.outer_parent_child_admission;
const channel = recursion.poseidon2_channel;
const fixed_wire = recursion.fixed_wire;
const pair_node = recursion.pair_node;
const protocol = recursion.protocol;
const source = recursion.outer_parent_statement_source;
const adapter = @import("recursive_parent_statement_source.zig");
const air_adapter = @import("recursive_parent_statement_air_source.zig");
const air_source = recursion.outer_parent_statement_air_source;
const segment_source = recursion.segment_statement_outer_source;
const outer = integration.recursive_fri_outer;

const Dimensions = fixed_wire.Dimensions{
    .commitment_count = admission.TREE_COUNT,
    .claimed_sum_count = admission.CLAIMED_SUM_COUNT,
    .sampled_value_count = admission.TREE_COUNT,
    .queried_value_count = admission.TREE_COUNT * admission.QUERY_COUNT,
    .trace_path_count = admission.TREE_COUNT * admission.QUERY_COUNT,
    .fri_layer_count = 5,
    .query_count = admission.QUERY_COUNT,
    .maximum_fold_width = 2,
    .last_layer_coefficient_count = 1,
    .maximum_merkle_depth = 6,
};
const Prepared = source.Prepared(Dimensions);
const Wire = admission.FixedOuterProofWireV1(Dimensions);

test "CPU parent statement adapter consumes exact VerifiedOuterProofV1 and fails atomically" {
    try std.testing.expect(!adapter.COMPLETE_PARENT_STARK_VERIFIED);
    try std.testing.expectEqual(@as(usize, 0), adapter.HEAP_ALLOCATIONS_PER_PREPARE);

    var invalid_verified: outer.VerifiedOuterProofV1 = undefined;
    @memset(std.mem.asBytes(&invalid_verified), 0);
    var invalid_wire: Wire = undefined;
    @memset(std.mem.asBytes(&invalid_wire), 0);
    var invalid_candidate: admission.BinaryPairCandidateV1 = undefined;
    @memset(std.mem.asBytes(&invalid_candidate), 0);

    const context = pair_node.VerifierContextV1{
        .session_id = digest(11),
        .job_id = digest(31),
        .execution_statement_id = digest(51),
        .public_call_commitment = protocol.emptyCallCommitment(),
        .event_count = 0,
        .session_leaf_count = 2,
        .pair_index = 0,
        .aggregator_vk_id = digest(71),
    };
    try context.validate();
    var invalid_authority: pair_node.VerifierAuthorityV1 = undefined;
    @memset(std.mem.asBytes(&invalid_authority), 0);
    invalid_authority.context = context;
    const suite = try pair_node.prepareProtocolSuite();
    const authority = source.AuthorityInputsV1{
        .pair = .{
            .context = context,
            .root_pin = .{ .expected_aggregator_vk_id = context.aggregator_vk_id },
        },
        .verified = &invalid_authority,
        .suite = &suite,
    };
    var invalid_binding: admission.PairChildInputsV1 = undefined;
    @memset(std.mem.asBytes(&invalid_binding), 0);
    const child = adapter.VerifiedChildInput(Dimensions){
        .verified = &invalid_verified,
        .wire = &invalid_wire,
        .candidate = &invalid_candidate,
        .binding = invalid_binding,
    };
    const scratch = try std.testing.allocator.alloc(
        u8,
        admission.serializedByteCount(Dimensions),
    );
    defer std.testing.allocator.free(scratch);
    var destination: Prepared = undefined;
    @memset(std.mem.asBytes(&destination), 0xd7);
    const snapshot = std.mem.asBytes(&destination)[0..@sizeOf(Prepared)].*;

    try std.testing.expectError(
        error.InvalidReceipt,
        adapter.prepareInto(
            Dimensions,
            &destination,
            scratch,
            authority,
            .{ child, child },
        ),
    );
    try std.testing.expectEqualSlices(
        u8,
        &snapshot,
        std.mem.asBytes(&destination),
    );
}

test "CPU fused parent AIR adapter preserves custody-first failure and performance budget" {
    try std.testing.expect(!air_adapter.COMPLETE_PARENT_STARK_VERIFIED);
    try std.testing.expect(air_adapter.NATIVE_VERIFIER_PUBLISHES_STATEMENT_WORDS);
    try std.testing.expect(!air_adapter.EXTERNAL_STATEMENT_PREIMAGE_BINDING);
    try std.testing.expectEqual(@as(usize, 1), air_adapter.PAIR_AUTHENTICATIONS_PER_PREPARE);
    try std.testing.expectEqual(@as(usize, 55), air_adapter.PAIR_PERMUTATIONS_PER_AUTHENTICATION);
    try std.testing.expectEqual(@as(usize, 229), air_adapter.PRIOR_STATIC_PAIR_PERMUTATION_ESTIMATE);
    try std.testing.expectEqual(@as(usize, 165), air_adapter.PAIR_PERMUTATIONS_AVOIDED);
    try std.testing.expectEqual(@as(usize, 0), air_adapter.HOT_PAIR_AUTHENTICATIONS_PER_TRACE_FILL);
    try std.testing.expectEqual(@as(usize, 0), air_adapter.HOT_TRACE_HEAP_ALLOCATIONS);

    var invalid_verified: outer.VerifiedOuterProofV1 = undefined;
    @memset(std.mem.asBytes(&invalid_verified), 0);
    var invalid_wire: Wire = undefined;
    @memset(std.mem.asBytes(&invalid_wire), 0);
    var invalid_candidate: admission.BinaryPairCandidateV1 = undefined;
    @memset(std.mem.asBytes(&invalid_candidate), 0);
    var invalid_binding: admission.PairChildInputsV1 = undefined;
    @memset(std.mem.asBytes(&invalid_binding), 0);

    const context = pair_node.VerifierContextV1{
        .session_id = digest(11),
        .job_id = digest(31),
        .execution_statement_id = digest(51),
        .public_call_commitment = protocol.emptyCallCommitment(),
        .event_count = 0,
        .session_leaf_count = 2,
        .pair_index = 0,
        .aggregator_vk_id = digest(71),
    };
    try context.validate();
    var invalid_authority: pair_node.VerifierAuthorityV1 = undefined;
    @memset(std.mem.asBytes(&invalid_authority), 0);
    invalid_authority.context = context;
    const suite = try pair_node.prepareProtocolSuite();
    const parent_inputs = source.AuthorityInputsV1{
        .pair = .{
            .context = context,
            .root_pin = .{ .expected_aggregator_vk_id = context.aggregator_vk_id },
        },
        .verified = &invalid_authority,
        .suite = &suite,
    };
    const child = adapter.VerifiedChildInput(Dimensions){
        .verified = &invalid_verified,
        .wire = &invalid_wire,
        .candidate = &invalid_candidate,
        .binding = invalid_binding,
    };
    const scratch = try std.testing.allocator.alloc(
        u8,
        admission.serializedByteCount(Dimensions),
    );
    defer std.testing.allocator.free(scratch);
    var unused_authority: segment_source.Authority = undefined;
    @memset(std.mem.asBytes(&unused_authority), 0);
    var unused_workspace: air_source.Workspace = undefined;
    @memset(std.mem.asBytes(&unused_workspace), 0);
    try std.testing.expectError(
        error.InvalidReceipt,
        air_adapter.prepare(
            Dimensions,
            std.testing.allocator,
            &unused_authority,
            &unused_workspace,
            scratch,
            parent_inputs,
            .{ child, child },
        ),
    );
}

fn digest(seed: u32) channel.Digest {
    var result: channel.Digest = undefined;
    for (&result, 0..) |*word, index|
        word.* = seed + @as(u32, @intCast(index * 2));
    return result;
}

src/integrations/riscv_cpu/recursive_v3_:
//! Shared geometry-only capture support for finalized V3 recorder tests.
//!
//! The sampled values are synthetic, but the manifest geometry is always
//! derived from a validated real component cohort.  This helper is test-only:
//! it supplies layout material to the recorder and is never a proof or
//! verifier authority.

const std = @import("std");
const stwo_core = @import("stwo_core");
const frontend = @import("stwo_riscv_frontend");
const integration = @import("stwo_riscv_cpu_integration");

const M31 = stwo_core.fields.m31.M31;
const QM31 = stwo_core.fields.qm31.QM31;
const CirclePointQM31 = stwo_core.circle.CirclePointQM31;
const recursion = frontend.recursion;
const binary_driver = integration.recursive_binary_outer;
const capture_layout = recursion.recursion_air_composition_circuit_v3
    .capture_layout_v3;

const FRI_LOG_BLOWUP: u32 = 1;
const COMPOSITION_COLUMN_COUNT: usize = 8;
const COMPOSITION_LOG_SPLIT: u32 =
    stwo_core.verifier_types.COMPOSITION_LOG_SPLIT;

pub fn syntheticCapture(
    allocator: std.mem.Allocator,
    manifest: anytype,
    seed: u32,
) !binary_driver.OuterProofCapture {
    const column_counts = [capture_layout.TREE_COUNT]usize{
        manifest.total_preprocessed_columns,
        manifest.total_main_columns,
        manifest.total_interaction_columns,
        COMPOSITION_COLUMN_COUNT,
    };
    const commitments = try allocator.alloc(
        recursion.engine.Hasher.Hash,
        capture_layout.TREE_COUNT,
    );
    for (commitments, 0..) |*commitment, index|
        commitment.* = nativeDigest(seed + @as(u32, @intCast(10 * index)));

    const points = try allocator.alloc(
        [][]CirclePointQM31,
        capture_layout.TREE_COUNT,
    );
    const logs = try allocator.alloc([]u32, capture_layout.TREE_COUNT);
    var sampled_value_count: usize = 0;
    const composition_log_size = deriveCompositionLogSize(manifest);
    for (column_counts, 0..) |column_count, tree| {
        points[tree] = try allocator.alloc([]CirclePointQM31, column_count);
        logs[tree] = try allocator.alloc(u32, column_count);
        for (points[tree], 0..) |*column_points, column_index| {
            const count = if (tree == capture_layout.INTERACTION_TREE_INDEX)
                interactionSamples(manifest, column_index)
            else
                1;
            column_points.* = try allocator.alloc(CirclePointQM31, count);
            @memset(column_points.*, CirclePointQM31.zero());
            sampled_value_count += count;
            logs[tree][column_index] = if (tree ==
                capture_layout.COMPOSITION_TREE_INDEX)
                composition_log_size - COMPOSITION_LOG_SPLIT + FRI_LOG_BLOWUP
            else
                traceColumnLog(manifest, tree, column_index) + FRI_LOG_BLOWUP;
        }
    }
    const sampled_values = try allocator.alloc(QM31, sampled_value_count);
    for (sampled_values, 0..) |*value, index|
        value.* = felt(seed + 100 + @as(u32, @intCast(index % 10_000)));

    return .{
        .queries = .{
            .raw = try allocator.alloc(usize, 0),
            .unique = try allocator.alloc(usize, 0),
        },
        .commitments = commitments,
        .column_log_sizes = logs,
        .sampled_points = points,
        .sampled_values = sampled_values,
        .queried_values = try allocator.alloc(M31, 0),
        .deep_answers = try allocator.alloc(QM31, 0),
        .trace_paths = try allocator.alloc(
            stwo_core.vcs_lifted.verifier.MerklePathCapture(
                recursion.engine.Hasher,
            ),
            0,
        ),
        .fri = .{ .layers = try allocator.alloc(
            stwo_core.fri.FriLayerQueryCapture(recursion.engine.Hasher),
            0,
        ) },
        .last_layer_coefficients = try allocator.alloc(QM31, 0),
        .proof_of_work = seed,
        .composition_randomness = felt(seed + 17),
        .oods_seed = felt(seed + 19),
        .deep_randomness = felt(seed + 23),
    };
}

pub fn nativeDigest(seed: u32) [8]u32 {
    var result: [8]u32 = undefined;
    for (&result, 0..) |*word, index|
        word.* = seed + @as(u32, @intCast(index));
    return result;
}

fn interactionSamples(manifest: anytype, column: usize) usize {
    for (manifest.roster_rows[0..manifest.roster_count]) |row| {
        const placement = manifest.placements[row].?;
        const start: usize = placement.interaction_offset;
        const end = start + placement.geometry.interaction_columns;
        if (column >= start and column < end) {
            if (row == binary_driver.POSEIDON_PROVIDER_ROW) return 2;
            return if (column >= end - 4) 2 else 1;
        }
    }
    unreachable;
}

fn traceColumnLog(manifest: anytype, tree: usize, column: usize) u32 {
    for (manifest.roster_rows[0..manifest.roster_count]) |row| {
        const placement = manifest.placements[row].?;
        const range = switch (tree) {
            capture_layout.PREPROCESSED_TREE_INDEX => .{
                placement.preprocessed_offset,
                placement.geometry.preprocessed_columns,
            },
            capture_layout.MAIN_TREE_INDEX => .{
                placement.main_offset,
                placement.geometry.main_columns,
            },
            capture_layout.INTERACTION_TREE_INDEX => .{
                placement.interaction_offset,
                placement.geometry.interaction_columns,
            },
            else => unreachable,
        };
        const start: usize = range[0];
        const end = start + range[1];
        if (column >= start and column < end)
            return placement.geometry.log_size;
    }
    unreachable;
}

fn deriveCompositionLogSize(manifest: anytype) u32 {
    var result: u32 = 0;
    for (manifest.roster_rows[0..manifest.roster_count]) |row| {
        const geometry = manifest.placements[row].?.geometry;
        const quotient_blowup = @max(
            @as(u32, 1),
            std.math.log2_int_ceil(
                u32,
                geometry.protocol_constraint_degree - 1,
            ),
        );
        result = @max(result, geometry.log_size + quotient_blowup);
    }
    return result;
}

fn felt(value: u32) QM31 {
    return QM31.fromBase(M31.fromCanonical(value));
}
